import {NATIONS,PLAYERS,CATALOGUE,configureCatalogue,canAfford,ROUND_COUNT,initialState,validSave,playerById,nationById,spent,average,createOffer,selectPlayer,sortBoards,startTournament,simulateRound,standings,rotateReserve,shuffle} from './engine.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={arrow:'↗',spin:'⟳',chevron:'→',check:'✓',close:'×',king:'♔',queen:'♕',rook:'♖',knight:'♘',bishop:'♗',pawn:'♙'};
const pieces=['king','queen','rook','knight','pawn'];
$('#main').innerHTML='<div class="content-wrap catalogue-loading" role="status">Opening the chess archive…</div>';
try{
  const response=await fetch('/api/catalog');
  if(!response.ok)throw new Error('Catalogue unavailable');
  configureCatalogue(await response.json());
}catch(error){
  $('#main').innerHTML='<div class="content-wrap catalogue-loading"><h1>The archive is taking a moment.</h1><p>Your saved game is still in this browser.</p><a class="primary-button" href="./">Try again</a></div>';
  throw error;
}
const SAVE_KEY='11-0-0:save:v2';
let saveNotice='';
let state=initialState(),selectedSlot=0,swapSlot=null,busy=false,selectedRound=null,view='matches',toastTimer,storageFailed=false;
try { const saved=JSON.parse(localStorage.getItem(SAVE_KEY));if(validSave(saved))state=saved;else if(saved)saveNotice='The archive has changed. A fresh draft is ready; your previous save is preserved in a backup.';else if(localStorage.getItem('11-0-0:save:v1'))saveNotice='Country-year drafting is here. Your older prototype save remains stored separately.'; } catch { /* A fresh draft is safe if browser storage is unavailable or invalid. */ }
if(saveNotice){try{const previous=localStorage.getItem(SAVE_KEY);if(previous)localStorage.setItem('11-0-0:save:v2:backup',previous);}catch{}}
selectedSlot=Math.max(0,state.squad.indexOf(null));
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch{if(!storageFailed){storageFailed=true;toast('Browser storage is unavailable. Keep this tab open to preserve your game.');}}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
const label=(n)=>n===0.5?'½':String(n).replace('.5','½');
const scoreLabel=(a,b)=>`${label(a)} – ${label(b)}`;
const count=()=>state.squad.filter(Boolean).length;
const revealed=()=>state.mode==='classic'||state.phase!=='draft';
const rating=p=>revealed()?p.rating:'????';

function stepper(){const phase=state.phase==='draft'?count()===5?1:0:state.phase==='results'?3:2;return `<div class="stepper" aria-label="Game progress">${['Draft your team','Set your boards','Play the Olympiad'].map((text,i)=>`<div class="step ${phase===i?'current':''} ${phase>i?'done':''}"><span>${phase>i?'✓':`0${i+1}`}</span>${text}</div>${i<2?'<div class="step-line"></div>':''}`).join('')}</div>`;}
function hero(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="tiny-diamond">✦</span> A WORLD OF TALENT. ONE DREAM TEAM.</div><h1>Four boards.<br>One <em>perfect run.</em></h1><p>Spin a country and year. Draft the greats. Build a team that can<br class="desktop-break"> go unbeaten at the Fantasy Chess Olympiad.</p></div><div class="hero-art" aria-hidden="true"><div class="orbital orbital-one"></div><div class="orbital orbital-two"></div><span class="art-star star-one">✦</span><span class="art-star star-two">✦</span><span class="art-small">♟</span><img class="art-knight" src="./knight.svg" alt=""><img class="art-king" src="./king.svg" alt=""><div class="art-caption"><span>THE PERFECT RECORD</span><strong>11 <i>–</i> 0 <i>–</i> 0</strong><small>WINS &nbsp; DRAWS &nbsp; LOSSES</small></div></div><div class="hero-bottom"><span><i></i> THE OLYMPIAD CHALLENGE</span><div>5 PLAYERS <b>·</b> 11 ROUNDS <b>·</b> ONE SHOT AT GOLD</div></div></section>`;}
function squadSlot(id,i){const p=playerById(id);return `<button class="squad-slot ${p?'filled':''} ${selectedSlot===i&&state.phase==='draft'?'selected':''} ${swapSlot===i?'swap-selected':''} ${i===4?'reserve-slot':''}" data-action="slot" data-slot="${i}" aria-label="${p?`${esc(p.name)}, ${i===4?'reserve':`board ${i+1}`}. Click to swap positions`:`Select ${i===4?'reserve':`board ${i+1}`} for your next pick`}" aria-pressed="${selectedSlot===i&&state.phase==='draft'}"><span class="slot-label">${i===4?'THE RESERVE':`BOARD 0${i+1}`} ${p?'<span class="slot-status">●</span>':''}</span>${p?`<span class="piece-token">${icons[pieces[i]]}</span><span class="slot-player">${esc(p.name)}</span><span class="slot-meta">${p.flag} ${p.federation} ${p.year} <b>·</b> ${rating(p)}</span><span class="slot-cost">${p.cost}<small> CR</small></span>`:`<span class="empty-piece">${icons[pieces[i]]}</span><span class="slot-empty">${i===4?'Your secret weapon':'Your next great'}</span><span class="slot-plus">+</span>`}</button>`;}
function squadPanel(){const complete=count()===5;return `<section class="squad-panel"><div class="panel-title"><div><span class="section-number">01 / YOUR LINEUP</span><h2>The dream team<span>.</span></h2></div><button class="text-button on-dark" data-action="team-name" aria-label="Rename team">${esc(state.teamName)} <span>✎</span></button></div><div class="board-surface"><div class="board-coordinate coordinate-top">a <span>b</span> c <span>d</span> e <span>f</span> g <span>h</span></div><div class="squad-grid">${state.squad.slice(0,4).map(squadSlot).join('')}</div><div class="reserve-row"><span class="reserve-note">FOUR MINDS.<br>ONE MISSION.</span>${squadSlot(state.squad[4],4)}<span class="reserve-note reserve-right">THE ROAD<br>TO 11–0–0.</span></div><div class="board-coordinate coordinate-bottom">a <span>b</span> c <span>d</span> e <span>f</span> g <span>h</span></div></div><div class="squad-summary"><div><span class="mini-label">PLAYERS DRAFTED</span><strong>${count()}<small> / 5</small></strong></div><div><span class="mini-label">TEAM RATING</span><strong>${count()?state.mode==='expert'?'????':average(state.squad.slice(0,4)):'—'}<small> ELO</small></strong></div><div class="squad-budget"><span class="mini-label">CREDITS LEFT</span><strong>${100-spent(state.squad)}<small> / 100</small></strong></div></div><div class="squad-panel-bottom"><span><span class="mint-dot"></span> ${complete?'Squad complete. Ready for the world.':'Select a board, then draft a player to fill it.'}</span><button class="text-button on-dark" data-action="sort">Order by rating ${icons.spin}</button></div></section>`;}

function candidateCard(id){
  const p=playerById(id),available=canAfford(p,state.squad),alreadyPicked=state.squad.filter(Boolean).some(id=>playerById(id).personId===p.personId);
  const reason=alreadyPicked?'Already in your squad':!available?'Not enough credits to finish your squad':'';
  return `<button class="candidate" data-action="pick" data-id="${p.id}" ${busy||!available?'disabled':''} aria-label="Draft ${esc(p.name)}, ${p.year}, ${state.mode==='classic'?p.rating+' adjusted game rating, ':''}${p.cost} credits${reason?', '+reason:''}"><span class="candidate-initial">${esc(p.name.split(' ').at(-1).slice(0,1))}<span>${p.flag}</span></span><span class="candidate-info"><span class="candidate-title">#${p.rank} IN ${p.federation} ${p.year} <span>${esc(p.title||'PLAYER')}</span></span><strong>${esc(p.name)}</strong><span class="candidate-rating">${rating(p)} <small>2026 GAME ELO</small></span><span class="source-rating">${revealed()?`${p.rawRating} ${p.estimated?'ESTIMATE':'FIDE'} · ${p.year}`:'Source rating hidden'}${reason?` · ${reason}`:''}</span></span><span class="candidate-end"><span class="price">${p.cost}<small>CR</small></span><span class="pick-arrow">↗</span></span></button>`;
}
function draftConsole(){const offer=state.offer,nation=offer?nationById(offer.nation):null,complete=count()===5;return `<section class="draft-console"><div class="console-top"><span class="section-number">02 / THE DRAFT</span><span class="draft-pick">PICK <strong>${Math.min(5,count()+1)}</strong> OF 5</span></div><h2>${complete?'A team worth believing in.':'Greatness is in the draw.'}</h2><p class="console-description">${complete?'Your five are ready. Set your boards and take on the world.':'A country. A year. Its five highest-rated players.<br>Who earns a place in your team?'}</p><div class="mode-switch" role="group" aria-label="Draft difficulty"><button data-action="mode" data-mode="classic" class="${state.mode==='classic'?'active':''}" ${count()||offer?'disabled':''}>Classic <span>Ratings visible</span></button><button data-action="mode" data-mode="expert" class="${state.mode==='expert'?'active':''}" ${count()||offer?'disabled':''}>Expert <span>Trust your instincts</span></button></div>${complete?`<div class="complete-draft"><span>♖</span><strong>The world is waiting.</strong><p>Four boards, eleven rounds.<br>How far can your team go?</p><div class="complete-stats"><span>${average(state.squad.slice(0,4))}<small>STARTING ELO</small></span><span>${100-spent(state.squad)}<small>CREDITS SAVED</small></span></div></div><button class="primary-button" data-action="start">Enter the Olympiad <span>→</span></button><p class="under-button">Click two players on your team to swap their positions.</p>`:`<div class="nation-draw ${offer?'drawn':''} ${busy?'spinning':''}" aria-live="polite"><div class="nation-flag">${nation?nation.flag:'✧'}</div><div><span>${nation?'YOUR FEDERATION DRAW':'THE WORLD IS YOUR PLAYER POOL'}</span><strong>${nation?`${esc(nation.name)} <b class="snapshot-year">${nation.year}</b>`:'Which country and year?'}</strong><small>${nation?`${nation.code} / TOP FIVE · ${nation.source.date}`:`${CATALOGUE.snapshotCount.toLocaleString()} country-year rolls · ${CATALOGUE.years.at(-1)}–2026`}</small></div>${nation?'<span class="nation-code">'+nation.code+'</span>':'<span class="globe-grid" aria-hidden="true">◎</span>'}</div>${offer?`<div class="candidate-list">${offer.players.map(candidateCard).join('')}</div><button class="snapshot-source text-button" data-action="snapshot-source">Rating list &amp; era adjustment ↗</button><button class="reroll-button" data-action="reroll" ${!state.rerolls||busy?'disabled':''}>⟳ &nbsp; Reroll nation <span>${state.rerolls} left</span></button><p class="under-button">Choose wisely. This pick is permanent.</p>`:`<div class="draw-empty"><div class="three-pieces" aria-hidden="true"><span>♗</span><span>♘</span><span>♖</span></div><p>Your next great player<br>is a spin away.</p></div><button class="primary-button" data-action="spin" ${busy?'disabled':''}><span class="spin-icon">⟳</span> ${busy?'Drawing your nation…':'Spin a nation'} <span>→</span></button><p class="under-button">${state.rerolls} nation rerolls available. Make them count.</p>`}`}</section>`;}
function bottomCards(){return `<section class="insight-row"><div class="insight"><span class="insight-icon">♙</span><div><strong>Build beyond borders</strong><p>Your dream team, drawn from across the world.</p></div></div><div class="insight"><span class="insight-icon">⚑</span><div><strong>The real team format</strong><p>Four active boards. One game-changing reserve.</p></div></div><div class="insight"><span class="insight-icon">✦</span><div><strong>Chase the impossible</strong><p>Eleven wins. No draws. No losses. Can you?</p></div></div></section>`;}
function renderDraft(){return `${hero()}<div class="content-wrap">${stepper()}<div class="game-toolbar"><div><button class="small-tag" data-action="archive">COUNTRIES &amp; YEARS ↗</button><span class="toolbar-subtitle">Your road to the podium starts here.</span></div><button class="text-button" data-action="quick">Quick draft <span>↗</span></button></div><div class="draft-layout">${squadPanel()}${draftConsole()}</div>${bottomCards()}<div class="reset-row"><span><span class="mint-dot"></span> Your progress saves automatically in this browser.</span><button class="text-button" data-action="reset">Start fresh ⟳</button></div></div>`;}

function userMatch(round){const m=state.tournament.rounds[round-1]?.find(m=>m.a==='YOU'||m.b==='YOU');if(!m)return null;const us=m.a==='YOU';return {...m,us,ourPoints:us?m.points:4-m.points,opponent:state.tournament.teams.find(t=>t.id===(us?m.b:m.a))};}
function matchDetails(round){const match=userMatch(round);if(!match)return `<div class="awaiting-match"><span>♔</span><h3>Your Olympiad starts here.</h3><p>Play the first round to meet your opening opponent.</p></div>`;const result=match.ourPoints>2?'Victory':match.ourPoints===2?'Draw':'Defeat';return `<div class="match-heading"><span>ROUND ${String(round).padStart(2,'0')} / MATCH REPORT</span><span class="result-pill ${result.toLowerCase()}">${result}</span></div><div class="match-score"><div><span class="team-emblem">✦</span><strong>${esc(state.teamName)}</strong><small>YOUR FANTASY TEAM</small></div><strong>${scoreLabel(match.ourPoints,4-match.ourPoints)}</strong><div><span class="team-emblem">${match.opponent.flag}</span><strong>${esc(match.opponent.name)}</strong><small>${match.opponent.rating} TEAM ELO</small></div></div><div class="board-results"><div class="board-results-head"><span>BOARD</span><span>YOUR GRANDMASTER</span><span>SCORE</span><span>OPPOSITION</span></div>${match.boards.map((b,i)=>{const us=match.us?b.a:b.b,other=match.us?b.b:b.a,points=match.us?b.score:1-b.score,white=match.us?b.white:!b.white;return `<div class="board-result"><span class="board-number">0${i+1}</span><div><strong><i class="color-dot ${white?'white':'black'}" title="${white?'White':'Black'} pieces"></i>${esc(us.name)}</strong><small>${us.rating} EFFECTIVE ELO</small></div><span class="board-score ${points===1?'win':points===0?'loss':''}">${scoreLabel(points,1-points)}</span><div><strong>${esc(other.name.replace(' · board', ' · #'))}</strong><small>${other.rating} GAME ELO</small></div></div>`;}).join('')}</div>`;}
function table(full=false){const rows=standings(state.tournament),me=rows.findIndex(t=>t.id==='YOU');let selected=full?rows:rows.slice(0,5);if(!full&&me>=5)selected=[...selected,rows[me]];return `<div class="standings-table"><div class="standings-row table-head"><span>#</span><span>TEAM</span><span>MP</span><span>BP</span>${full?'<span>SB</span>':''}</div>${selected.map(t=>`<div class="standings-row ${full?'full':''} ${t.id==='YOU'?'you':''}"><span>${rows.indexOf(t)+1}</span><strong><span class="table-flag">${t.flag}</span>${esc(t.name)}${t.id==='YOU'?'<small>YOU</small>':''}</strong><b>${t.mp}</b><span>${label(t.bp)}</span>${full?`<span>${label(t.sb)}</span>`:''}</div>`).join('')}</div>`;}
function tournamentSquad(){const t=state.tournament;return `<div class="live-squad"><div class="live-squad-title"><span class="section-number">YOUR MATCHDAY FIVE</span><button class="text-button" data-action="rotate" ${state.phase==='results'?'disabled':''}>Rotate reserve ⟳</button></div><div class="live-player-list">${t.squad.map((id,i)=>{const p=playerById(id),fatigue=Math.min(40,Math.max(0,t.streaks[id]-3)*8);return `<div class="live-player"><span class="live-player-position">${i===4?'R':`0${i+1}`}</span><span>${p.flag}</span><strong>${esc(p.name)}<small>${i===4?'RESERVE · RESTING':fatigue?`${p.rating-fatigue} ELO · FATIGUE −${fatigue}`:`${p.rating} ELO · READY`}</small></strong><span class="energy ${i===4?'resting':''}" title="${i===4?'Resting':`${t.streaks[id]} consecutive rounds`}">${i===4?'↺':'●'}</span></div>`;}).join('')}</div></div>`;}
function renderTournament(){const t=state.tournament,done=state.phase==='results',me=t.teams.find(x=>x.id==='YOU'),rank=standings(t).findIndex(x=>x.id==='YOU')+1,perfect=me.w===11;const round=selectedRound||t.round;return `<div class="tournament-hero"><div class="content-wrap"><span class="eyebrow"><span class="tiny-diamond">✦</span> ${done?'THE FINAL STANDING':'YOUR ROAD TO GOLD'}</span><h1>${done?perfect?'The perfect <em>eleven.</em>':rank===1?'On top of <em>the world.</em>':rank<=3?'A place on <em>the podium.</em>':'A run to <em>remember.</em>':'One team. <em>All in.</em>'}</h1><div class="tournament-hero-bottom"><p>${done?`You finished ${ordinal(rank)} of 32. ${perfect?'Eleven wins. You made the impossible happen.':rank===1?'Olympiad champions. What a team.':'Every great run starts with a dream team.'}`:`${esc(state.teamName)} · Fantasy Olympiad · Round ${t.round} of 11`}</p><span class="live-tag"><i></i> ${done?'TOURNAMENT COMPLETE':'TOURNAMENT IN PROGRESS'}</span></div></div></div><div class="content-wrap tournament-content"><section class="tournament-stats"><div><span>MATCH RECORD</span><strong>${me.w}<i>–</i>${me.d}<i>–</i>${me.l}</strong><small>WINS · DRAWS · LOSSES</small></div><div><span>WORLD RANK</span><strong>${String(rank).padStart(2,'0')}<small> / 32</small></strong><small>${rank<=3?'PODIUM POSITION':'KEEP CLIMBING'}</small></div><div><span>MATCH POINTS</span><strong>${me.mp}<small> / ${t.round*2||22}</small></strong><small>2 FOR A WIN · 1 FOR A DRAW</small></div><div><span>BOARD POINTS</span><strong>${label(me.bp)}<small> / ${t.round*4||44}</small></strong><small>EVERY BOARD COUNTS</small></div></section><div class="tournament-layout"><section class="match-panel"><div class="match-panel-toolbar"><div class="view-tabs" role="group" aria-label="Tournament view"><button class="${view==='matches'?'active':''}" data-action="view" data-view="matches">Your matches</button><button class="${view==='standings'?'active':''}" data-action="view" data-view="standings">Full standings</button></div><span class="section-number">11 ROUNDS. ONE DREAM.</span></div>${view==='standings'?table(true):`<div class="round-tabs" role="group" aria-label="Select round">${Array.from({length:11},(_,i)=>{const m=userMatch(i+1);return `<button data-action="round" data-round="${i+1}" class="${round===i+1?'active':''} ${m?m.ourPoints>2?'won':m.ourPoints===2?'drawn':'lost':''}" ${i>=t.round?'disabled':''} aria-label="Round ${i+1}${m?m.ourPoints>2?', won':m.ourPoints===2?', drawn':', lost':', unplayed'}">${String(i+1).padStart(2,'0')}<span></span></button>`;}).join('')}</div>${matchDetails(round)}`}</section><aside class="tournament-aside">${tournamentSquad()}<div class="next-round">${done?`<div class="finish-medal">${rank===1?'♕':rank<=3?'♖':'♘'}</div><strong>${perfect?'11–0–0. Legendary.':rank===1?'Gold looks good on you.':'The next run could be the one.'}</strong><button class="primary-button" data-action="share">Copy result <span>↗</span></button><button class="secondary-button" data-action="reset">Build another team ⟳</button>`:`<div class="next-round-label"><span class="mint-dot"></span> NEXT UP / ROUND ${String(t.round+1).padStart(2,'0')}</div><p>${t.round===0?'The first move is yours.':t.round===10?'One last round. Make it count.':'New round. New opponent.'}</p><button class="primary-button" data-action="next" ${busy?'disabled':''}>${busy?'Playing the boards…':`Play round ${t.round+1}`} <span>→</span></button><button class="text-button simulate-all" data-action="finish" ${busy?'disabled':''}>Simulate remaining rounds ↗</button>`}</div></aside></div>${done?'':`<div class="mini-leaderboard"><div class="mini-leaderboard-heading"><h3>The chasing pack<span>.</span></h3><button class="text-button" data-action="view" data-view="standings">All 32 teams ↗</button></div>${table()}</div>`}<div class="reset-row"><span><span class="mint-dot"></span> ${done?'Game ratings and simulated results. Your own alternate chess universe.':'Progress saved. Rotate your reserve to manage player fatigue.'}</span><button class="text-button" data-action="reset">New draft ⟳</button></div></div>`;}
function ordinal(n){return `${n}${n%100>=11&&n%100<=13?'th':({1:'st',2:'nd',3:'rd'})[n%10]||'th'}`;}
function render(){const focus=document.activeElement;const focusData={...focus?.dataset},focusAction=focusData.action;$('#main').innerHTML=state.phase==='draft'?renderDraft():renderTournament();save();if(focusAction){const candidates=[...document.querySelectorAll(`[data-action="${focusAction}"]`)];(candidates.find(el=>!el.disabled&&Object.entries(focusData).every(([key,value])=>el.dataset[key]===value)))?.focus({preventScroll:true});}}
function modal(html){$('#dialog-content').innerHTML=`<button class="dialog-close" data-action="close" aria-label="Close dialog">×</button>${html}`;if(!$('#dialog').open)$('#dialog').showModal();}
function archive(){
  const years=CATALOGUE.years;
  modal(`<span class="section-number">THE CHESS ARCHIVE</span><h2 id="dialog-title">Countries. Years. Great players.</h2><p class="dialog-lead">${CATALOGUE.snapshotCount.toLocaleString()} country-year rolls across ${CATALOGUE.countryCount} federation codes. Each roll shows the five highest-rated players in its source list, regardless of Olympiad participation.</p><label class="input-label" for="archive-year">EXPLORE A SNAPSHOT YEAR</label><select id="archive-year">${years.map(year=>`<option value="${year}">${year}</option>`).join('')}</select><div id="archive-countries"></div><div class="rules-note"><strong>A fairer meeting of eras.</strong><p>Game Elo = published rating + (${CATALOGUE.referenceMedian} − that year's world top-100 median), rounded to the nearest point. This preserves within-era rating gaps. It is a game adjustment, not an official FIDE conversion or a claim about absolute strength.</p><strong>Earlier history is still being verified.</strong><p>${CATALOGUE.missingYears.length?`Years awaiting an audited country top five: ${CATALOGUE.missingYears.join(', ')}.`:'Every scheduled year is represented. Early country coverage is selective; only audited top fives are available.'} Pre-1971 ratings are historical estimates. We have sourced those estimates back to 1927, and only country top fives with verified affiliations become rollable.</p></div><button class="primary-button" data-action="close">Back to the draft →</button>`);
  renderArchiveYear(years[0]);
}
function renderArchiveYear(year){
  const nations=NATIONS.filter(n=>n.year===Number(year));
  $('#archive-countries').innerHTML=`<p class="archive-summary">${nations.length} country snapshots · list dated ${nations[0]?.source.date||'—'}</p><div class="archive-grid">${nations.map(n=>`<button data-action="archive-country" data-id="${n.id}">${n.flag} ${esc(n.name)} <span>${n.year}</span></button>`).join('')}</div>`;
}
function snapshotSource(id=state.offer?.nation){
  const nation=nationById(id);if(!nation)return;
  modal(`<span class="section-number">${esc(nation.code)} / ${nation.year}</span><h2 id="dialog-title">${nation.flag} ${esc(nation.name)} ${nation.year}</h2><p class="dialog-lead">The source list's top five by source rating. Players are included regardless of whether they played in that year's Olympiad. Explicitly inactive players are excluded when activity flags are available.</p><div class="source-roster">${nation.players.map(id=>{const p=playerById(id);return `<div><span>${p.rank}. ${esc(p.name)}</span><strong>${p.rawRating} <small>${p.estimated?'ESTIMATE':'FIDE'}</small> → ${p.rating} <small>GAME</small></strong></div>`;}).join('')}</div><p class="dialog-lead">List date: ${nation.source.date}. Era adjustment: ${nation.adjustment>=0?'+':''}${nation.adjustment} Elo before rounding.</p><div class="rules-note">${nation.source.notes.map(note=>`<p>${esc(note)}</p>`).join('')}<a href="${esc(nation.source.url)}" target="_blank" rel="noopener">Open the rating source ↗</a></div><button class="primary-button" data-action="archive">Explore other years →</button>`);
}
function rules(){modal(`<span class="section-number">THE PLAYBOOK</span><h2 id="dialog-title">Five minds.<br>One perfect run.</h2><p class="dialog-lead">A fantasy team builder inspired by <a href="https://38-0-0.com/" target="_blank" rel="noopener">38–0–0</a>. Your challenge: win all eleven rounds.</p><ol class="rules-list"><li><span>01</span><div><strong>Spin. Choose. Repeat.</strong><p>Draw a country-year snapshot and choose from its five highest-rated listed players. Unaffordable players and people already drafted stay visible but cannot be picked. You have 100 credits for four active players and one reserve. Two nation rerolls give you a second chance. Picks cannot be undone.</p></div></li><li><span>02</span><div><strong>Find your best four.</strong><p>Select an empty board before drafting. Click two filled slots to swap players. Active boards automatically sort by game rating when you enter the Olympiad.</p></div></li><li><span>03</span><div><strong>Take on the world.</strong><p>Play eleven rounds against 31 national teams. A board win is 1 point, a draw ½. Win the four-board match for 2 match points, or draw it for 1. Similar scores are paired with no rematches.</p></div></li><li><span>04</span><div><strong>Keep something in reserve.</strong><p>After four consecutive games, a player loses 8 effective Elo per extra round, up to 40. Rotate your reserve between rounds; sitting out resets fatigue. Higher Elo improves your chances, but guarantees nothing.</p></div></li></ol><div class="rules-note"><strong>A fantasy, grounded in chess.</strong><p>Sourced FIDE ratings and clearly labelled historical estimates are adjusted to a January 2026 game scale. Top-five selection uses source ratings and federation, independent of Olympiad participation. A 32-team field, simplified Swiss pairings and simplified Sonneborn–Berger tiebreaks keep this prototype quick. No actual chess moves are played. Expert mode hides Elo during the draft; credit prices still hint at strength.</p><a href="https://handbook.fide.com/files/handbook/Olympiad2024.pdf" target="_blank" rel="noopener">The real Olympiad format ↗</a></div><button class="primary-button" data-action="close">Let's play <span>→</span></button>`);}
function newDraft(){state=initialState();selectedSlot=0;swapSlot=null;selectedRound=null;view='matches';busy=false;$('#dialog').close();render();window.scrollTo({top:0,behavior:'smooth'});toast('A fresh board. A new possibility.');}
function reset(){if(!count()&&!state.offer){newDraft();return;}modal(`<span class="section-number">A CLEAN SLATE</span><h2 id="dialog-title">One more run?</h2><p class="dialog-lead">This replaces your current team and tournament with a fresh draft.</p><button class="primary-button" data-action="confirm-reset">Start a new draft <span>→</span></button><button class="secondary-button" data-action="close">Keep my team</button>`);}
async function spin(reroll=false){if(busy||count()>=5||(!reroll&&state.offer)||(reroll&&(!state.offer||!state.rerolls)))return;busy=true;render();await new Promise(r=>setTimeout(r,550));state.offer=createOffer(state.squad);if(reroll)state.rerolls--;busy=false;render();document.querySelector('.candidate')?.focus({preventScroll:true});}
function quick(){if(count())modal(`<span class="section-number">LET FATE PICK YOUR FIVE</span><h2 id="dialog-title">Finish the draft?</h2><p class="dialog-lead">Keep your existing picks and let the assistant choose affordable grandmasters for the remaining boards.</p><button class="primary-button" data-action="confirm-quick">Complete my team <span>→</span></button><button class="secondary-button" data-action="close">Back to the draft</button>`);else quickDraft();}
function quickDraft(){while(count()<5){if(!state.offer)state.offer=createOffer(state.squad);const candidates=shuffle(state.offer.players.filter(id=>canAfford(playerById(id),state.squad)));state=selectPlayer(state,candidates[0],state.squad.indexOf(null));}state.squad=sortBoards(state.squad);$('#dialog').close();render();toast('Your five are ready. Review your lineup and enter the Olympiad.');}
async function advance(all=false){if(busy||state.phase!=='tournament')return;busy=true;render();await new Promise(r=>setTimeout(r,all?650:400));try {do{state.tournament=simulateRound(state.tournament);}while(all&&state.tournament.round<11);selectedRound=state.tournament.round;view='matches';if(state.tournament.round===11)state.phase='results';}catch{toast('The round could not be completed. Your last saved round is safe.');}finally{busy=false;render();}}
function rotate(){if(state.phase!=='tournament'||busy)return;const t=state.tournament,p=playerById(t.squad[4]);modal(`<span class="section-number">A FRESH MIND AT THE BOARD</span><h2 id="dialog-title">Make your move.</h2><p class="dialog-lead">Bring in ${esc(p.name)} (${p.rating} Elo). Choose who sits out round ${t.round+1}. Boards will reorder by rating.</p><div class="rotation-options">${t.squad.slice(0,4).map((id,i)=>{const p=playerById(id);return `<button class="rotation-option" data-action="rotate-pick" data-slot="${i}"><span>${p.flag}</span><strong>${esc(p.name)}<small>${p.rating} ELO · ${t.streaks[id]} CONSECUTIVE ROUNDS</small></strong><span>↔</span></button>`;}).join('')}</div>`);}
async function share(){const t=state.tournament,me=t.teams.find(x=>x.id==='YOU'),rank=standings(t).findIndex(x=>x.id==='YOU')+1;const result=`11–0–0 · Fantasy Chess Olympiad\n${state.teamName}: ${me.w}–${me.d}–${me.l} | ${ordinal(rank)} / 32 | ${me.mp} match points\n${t.squad.slice(0,4).map(id=>playerById(id).name).join(' · ')}\nBuild your dream team: ${location.origin}${location.pathname}`;try{await navigator.clipboard.writeText(result);toast('Result copied. Your dream team deserves an audience.');}catch{modal(`<span class="section-number">YOUR OLYMPIAD RESULT</span><h2 id="dialog-title">A run worth sharing.</h2><p class="dialog-lead">Copy your result below.</p><textarea class="share-text" readonly aria-label="Result to copy">${esc(result)}</textarea><button class="primary-button" data-action="close">Done <span>✓</span></button>`);$('.share-text').select();}}
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;
  if(busy&&!['rules','about','close','game'].includes(action))return;
  if(action==='rules')rules();
  if(action==='archive')archive();if(action==='archive-country')snapshotSource(target.dataset.id);if(action==='snapshot-source')snapshotSource();
  if(action==='about')modal(`<span class="section-number">INDEPENDENT BY DESIGN</span><h2 id="dialog-title">Chess. Reimagined.</h2><p class="dialog-lead">11–0–0 is an independent, unofficial prototype inspired by the random-draft football game <a href="https://38-0-0.com/" target="_blank" rel="noopener">38–0–0</a> and the team format of the Chess Olympiad.</p><p>Player names are real; historical ratings and labelled estimates come from sourced lists; adjusted strengths, prices and results are game data. This is not affiliated with FIDE, the Olympiad or 38–0–0. Your game saves in this browser.</p><button class="primary-button" data-action="close">Back to the board <span>→</span></button>`);
  if(action==='close')$('#dialog').close();
  if(action==='game')$('#main').scrollIntoView({behavior:'smooth'});
  if(action==='spin')await spin();
  if(action==='reroll')await spin(true);
  if(action==='mode'&&!count()&&!state.offer){state.mode=target.dataset.mode;render();}
  if(action==='pick'){const old=count();if(state.squad[selectedSlot])selectedSlot=state.squad.indexOf(null);state=selectPlayer(state,target.dataset.id,selectedSlot);if(count()>old){const p=playerById(target.dataset.id);selectedSlot=Math.max(0,state.squad.indexOf(null));swapSlot=null;render();toast(`${p.name} joins your team.`);document.querySelector(count()===5?'[data-action="start"]':'[data-action="spin"]')?.focus({preventScroll:true});}}
  if(action==='slot'&&state.phase==='draft'){const i=Number(target.dataset.slot);if(!state.squad[i]){selectedSlot=i;swapSlot=null;}else if(swapSlot===null){swapSlot=i;toast('Select another filled slot to swap, or an empty slot to draft.');}else{[state.squad[swapSlot],state.squad[i]]=[state.squad[i],state.squad[swapSlot]];swapSlot=null;}render();}
  if(action==='sort'){if(state.mode==='expert'&&count()<5){toast('Automatic ordering is available when the draft is complete.');return;}state.squad=sortBoards(state.squad);selectedSlot=Math.max(0,state.squad.indexOf(null));swapSlot=null;render();toast('Your active boards are ordered by game rating.');}
  if(action==='team-name')modal(`<span class="section-number">MAKE IT YOURS</span><h2 id="dialog-title">Name your team.</h2><form id="team-form"><label class="input-label" for="team-name">TEAM NAME</label><input id="team-name" name="teamName" value="${esc(state.teamName)}" maxlength="30" required autocomplete="off"><button class="primary-button" type="submit">Save team name <span>✓</span></button></form>`);
  if(action==='quick')quick();if(action==='confirm-quick')quickDraft();
  if(action==='start'&&count()===5){state.tournament=startTournament(state.squad,state.teamName);state.squad=[...state.tournament.squad];state.phase='tournament';selectedRound=null;render();window.scrollTo({top:0,behavior:'smooth'});}
  if(action==='next')await advance();if(action==='finish')await advance(true);
  if(action==='round'){selectedRound=Number(target.dataset.round);render();}
  if(action==='view'){view=target.dataset.view;render();}
  if(action==='rotate')rotate();
  if(action==='rotate-pick'){state.tournament=rotateReserve(state.tournament,Number(target.dataset.slot));$('#dialog').close();render();toast('Reserve rotated in. Your boards have been reordered.');}
  if(action==='reset')reset();if(action==='confirm-reset')newDraft();if(action==='share')await share();
});
document.addEventListener('submit',event=>{if(event.target.id!=='team-form')return;event.preventDefault();const name=$('#team-name').value.trim();if(!name){$('#team-name').setCustomValidity('Give your team a name.');$('#team-name').reportValidity();return;}state.teamName=name;$('#dialog').close();render();});
document.addEventListener('change',event=>{if(event.target.id==='archive-year')renderArchiveYear(event.target.value);});
document.addEventListener('input',event=>{if(event.target.id==='team-name')event.target.setCustomValidity('');});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const rect=$('#dialog').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('#dialog').close();}});
render();
if(saveNotice)toast(saveNotice);
